// Screen 2 of 29. Generated by Google Stitch, source folder 2-search_results.
//
// WIRED 4 August 2026. It was a StatelessWidget rendering the same hardcoded
// card four times: "The Riverside Apartment", "£112 per night", "18 GoOuts
// partners within half a mile", one Unsplash URL, and a fixed
// "Richmond, 12 to 14 July".
//
// Everything below now comes from StayAvailabilityService.search.
//
// ── TWO THINGS THIS SCREEN IS CAREFUL ABOUT ─────────────────────────────────
//
// 1. IT SAYS WHEN THE DATES WERE IGNORED.
//    Stage 1 search cannot filter by availability — Firestore cannot answer
//    "free between these two dates" (see the service). So when a guest has
//    picked dates, this screen shows a banner saying they have not been
//    applied. Silently dropping a date filter would show somebody a property
//    that is already booked, and let them believe otherwise.
//
// 2. IT DOES NOT INVENT A PARTNER COUNT.
//    The mock card always claimed 18 partners. The real headline is null when
//    there is nothing nearby to claim, and a null headline renders as nothing.
//    Better a card with no badge than a badge with a made up number.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_listing.dart';
import '../services/stay_availability_service.dart';
import '../services/stay_booking_service.dart';
// For watchSaved / setSaved on the card heart. Both existed and nothing called
// them until 28 August 2026.
import '../services/stay_listing_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';
import '../widgets/stay_bottom_nav.dart';

class SearchResultsScreen extends StatefulWidget {
  const SearchResultsScreen({super.key, this.criteria});

  /// Passed by the home screen. Defaults to "everything, cheapest journey
  /// first" so the screen is still useful when opened directly.
  final StaySearchCriteria? criteria;

  @override
  State<SearchResultsScreen> createState() => _SearchResultsScreenState();
}

class _SearchResultsScreenState extends State<SearchResultsScreen> {
  late StaySearchCriteria _criteria;
  StaySearchPage _page = StaySearchPage.empty;
  bool _loading = true;

  /// Platform wide and identical on every card, so fetched once per screen.
  StayCashbackRate _rate = StayCashbackRate.unknown;
  String? _error;

  @override
  void initState() {
    super.initState();
    _criteria = widget.criteria ?? const StaySearchCriteria();
    _load();
  }

  /// cashbackRate swallows its own failures and returns `unknown`, so a
  /// cashback outage costs the chip on each card and nothing else.
  Future<void> _loadRate() async {
    final StayCashbackRate r =
        await StayBookingService.instance.cashbackRate();
    if (!mounted) return;
    setState(() => _rate = r);
  }

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      // ── ⚠ THE RATE IS NOT AWAITED HERE. Fixed 22 August 2026. ─────────
      //
      // It used to be `await search(...)` and then `await cashbackRate()`, in
      // sequence, with _loading staying true until both returned. The search
      // is a Firestore read; cashbackRate is a Cloud Function, and a function
      // idle for fifteen minutes COLD STARTS — seconds, not milliseconds. So
      // the results sat behind a spinner waiting for a label.
      //
      // Started here, applied whenever it lands. _rate defaults to
      // StayCashbackRate.unknown and every use of it is behind
      // `_rate.isKnown`, so arriving late costs a chip appearing a moment
      // after the cards.
      _loadRate();

      final page = await StayAvailabilityService.instance
          .search(_criteria)
          .timeout(const Duration(seconds: 20));
      if (!mounted) return;
      setState(() {
        _page = page;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        // The real reason, not "something went wrong". A permission denied
        // here means the rules are not deployed, and that is worth being able
        // to see rather than guess at.
        _error = e.toString();
      });
    }
  }

  String get _subtitle {
    final parts = <String>[];
    if (_criteria.hasDates) {
      parts.add('${_d(_criteria.checkIn!)} to ${_d(_criteria.checkOut!)}');
    }
    parts.add('${_criteria.guests} '
        '${_criteria.guests == 1 ? 'guest' : 'guests'}');
    return parts.join('  •  ');
  }

  static String _d(DateTime d) {
    const m = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return '${d.day} ${m[d.month - 1]}';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GoOutsColors.pageBackground,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0.5,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          onPressed: () => Navigator.of(context).maybePop(),
        ),
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              _criteria.town ?? 'Anywhere in the UK',
              style: GoogleFonts.inter(
                fontSize: 15,
                fontWeight: FontWeight.w700,
                color: GoOutsColors.deepNavy,
              ),
            ),
            Text(
              _subtitle,
              style: GoogleFonts.inter(
                fontSize: 12,
                fontWeight: FontWeight.w500,
                color: GoOutsColors.bodyText,
              ),
            ),
          ],
        ),
      ),
      bottomNavigationBar: const StayBottomNav(current: StayTab.search),
      body: Column(
        children: [
          _buildUtilityBar(),
          if (_criteria.hasDates && !_page.datesApplied && !_loading)
            _datesNotAppliedBanner(),
          Expanded(child: _body()),
        ],
      ),
    );
  }

  Widget _body() {
    if (_loading) return _skeletons();
    if (_error != null) {
      return _message(
        Icons.error_outline,
        'Could not load places to stay',
        _error!,
        onRetry: _load,
      );
    }
    if (_page.listings.isEmpty) {
      return _message(
        Icons.search_off,
        'Nothing matches yet',
        'Try widening the filters, or searching a different town.',
      );
    }
    final int n = _page.listings.length;
    return RefreshIndicator(
      color: GoOutsColors.primaryBlue,
      onRefresh: _load,
      child: ListView.separated(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),
        // One extra row at the top for the count.
        itemCount: n + 1,
        separatorBuilder: (_, __) => const SizedBox(height: 14),
        itemBuilder: (context, i) {
          if (i == 0) {
            return Text(
              // The real number, from the real result set. A search that
              // found three places says three.
              n == 1 ? '1 place to stay' : '$n places to stay',
              style: GoogleFonts.inter(
                fontSize: 13.5,
                fontWeight: FontWeight.w600,
                color: GoOutsColors.bodyText,
              ),
            );
          }
          return _buildPropertyCard(_page.listings[i - 1]);
        },
      ),
    );
  }

  /// Blocks in the shape of the cards. A bare spinner gives no sense of what
  /// is coming, and the page jumps when the results replace it.
  Widget _skeletons() {
    Widget box(double h, double w, [double r = 8]) => Container(
          height: h,
          width: w,
          decoration: BoxDecoration(
            color: GoOutsColors.dividerGray,
            borderRadius: BorderRadius.circular(r),
          ),
        );

    return ListView.separated(
      padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
      itemCount: 3,
      separatorBuilder: (_, __) => const SizedBox(height: 14),
      itemBuilder: (_, __) => Container(
        decoration: BoxDecoration(
          color: GoOutsColors.cardSurface,
          borderRadius: BorderRadius.circular(14),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            box(180, double.infinity, 14),
            const SizedBox(height: 14),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: box(15, 220),
            ),
            const SizedBox(height: 10),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: box(12, 140),
            ),
            const SizedBox(height: 16),
          ],
        ),
      ),
    );
  }

  /// The honesty banner. See the header.
  Widget _datesNotAppliedBanner() => Container(
        width: double.infinity,
        color: GoOutsColors.warning.withValues(alpha: 0.15),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
        child: Row(
          children: [
            const Icon(Icons.info_outline,
                size: 16, color: GoOutsColors.deepNavy),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                'Showing all places in this area. We cannot check which are '
                'free on your dates yet, so check availability before booking.',
                style: GoogleFonts.inter(
                    fontSize: 12, color: GoOutsColors.deepNavy),
              ),
            ),
          ],
        ),
      );

  Widget _message(IconData icon, String title, String detail,
          {VoidCallback? onRetry}) =>
      Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 44, color: GoOutsColors.outlineVariant),
              const SizedBox(height: 12),
              Text(title,
                  textAlign: TextAlign.center,
                  style: GoogleFonts.inter(
                      fontSize: 16,
                      fontWeight: FontWeight.w700,
                      color: GoOutsColors.deepNavy)),
              const SizedBox(height: 6),
              Text(detail,
                  textAlign: TextAlign.center,
                  style: GoogleFonts.inter(
                      fontSize: 12, color: GoOutsColors.bodyText)),
              if (onRetry != null) ...[
                const SizedBox(height: 16),
                TextButton(onPressed: onRetry, child: const Text('Try again')),
              ],
            ],
          ),
        ),
      );

  Widget _buildUtilityBar() {
    return Container(
      color: Colors.white,
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Row(
            children: [
              _buildUtilityButton(Icons.tune, 'Filters', () async {
                final next = await Navigator.of(context)
                    .pushNamed(StayRoutes.filters, arguments: {
                  'criteria': _criteria,
                });
                if (!mounted) return;
                if (next is StaySearchCriteria) {
                  setState(() => _criteria = next);
                  _load();
                }
              }),
              const SizedBox(width: 8),
              _buildUtilityButton(Icons.swap_vert, _criteria.sort.label,
                  _pickSort),
            ],
          ),
          // ⚠ HANDS THE RESULTS OVER. Fixed 29 August 2026. This pushed the
          // map route with no arguments at all, and the map screen — which has
          // always accepted a listings list — received an empty one and drew
          // its "Nothing to show on the map" state every single time.
          //
          // The list is PASSED rather than re-queried on the other side so the
          // two views cannot disagree, and so opening the map costs no second
          // Firestore read. The criteria goes with it for the header.
          _buildUtilityButton(Icons.map, 'Map', () {
            Navigator.of(context).pushNamed(
              StayRoutes.map,
              arguments: <String, dynamic>{
                'listings': _page.listings,
                'criteria': _criteria,
              },
            );
          }),
        ],
      ),
    );
  }

  Future<void> _pickSort() async {
    final chosen = await showModalBottomSheet<StaySort>(
      context: context,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
      ),
      builder: (ctx) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            for (final s in StaySort.values)
              ListTile(
                title: Text(s.label, style: GoogleFonts.inter(fontSize: 14)),
                trailing: s == _criteria.sort
                    ? const Icon(Icons.check, color: GoOutsColors.primaryBlue)
                    : null,
                onTap: () => Navigator.of(ctx).pop(s),
              ),
          ],
        ),
      ),
    );
    if (!mounted || chosen == null) return;
    setState(() => _criteria = _criteria.copyWith(sort: chosen));
    _load();
  }

  Widget _buildUtilityButton(IconData icon, String label, VoidCallback onTap) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(20),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        decoration: BoxDecoration(
          border: Border.all(color: Colors.grey.shade300),
          borderRadius: BorderRadius.circular(20),
        ),
        child: Row(
          children: [
            Icon(icon, size: 16, color: GoOutsColors.deepNavy),
            const SizedBox(width: 4),
            ConstrainedBox(
              // The sort labels are long. Without this the row overflows on a
              // narrow phone, which is a yellow-and-black stripe on screen.
              constraints: const BoxConstraints(maxWidth: 150),
              child: Text(
                label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: GoogleFonts.inter(
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                  color: GoOutsColors.deepNavy,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _photoChip(String text,
          {required Color colour, IconData? icon}) =>
      Container(
        padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
        decoration: BoxDecoration(
          color: colour,
          borderRadius: BorderRadius.circular(20),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            if (icon != null) ...<Widget>[
              Icon(icon, size: 12, color: Colors.white),
              const SizedBox(width: 5),
            ],
            Text(
              text,
              style: GoogleFonts.inter(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: Colors.white,
              ),
            ),
          ],
        ),
      );

  // ── The property card, rebuilt to Stitch 2-search_results, 28 August 2026 ──
  //
  // ── ⚠ THE PARTNER COUNT WAS A GREY FOOTNOTE ON THE BROWSE SCREEN ───────────
  //
  // Stitch runs it as a SOLID BLUE BANNER across the full width of every card,
  // directly under the transport line, and it is the strongest thing on the
  // card by a distance. Ours had it twice and quietly: a translucent chip on
  // the photograph, and a small rounded pill at the bottom under the price.
  //
  // This is the screen where a guest compares us against Airbnb. A photograph
  // and a price are what every other app shows. "14 GoOuts partners within half
  // a mile" is the only line on the card that no other app can write, and it
  // was the least prominent thing on it.
  //
  // ⚠ AND IT IS RENDERED ONCE. It appeared as both a photo chip and a footer
  // pill, which is the same fact twice on one card.
  //
  // ── ⚠ THE TRANSPORT LINE NOW USES THE STATION, NOT THE CITY CENTRE ─────────
  //
  // Stitch says "0.4 miles from Wembley Park, Jubilee and Metropolitan lines".
  // We were saying "2.1 miles from Central London", which is a worse answer to
  // the question a guest is actually asking, and StayStation has carried name,
  // lines and walkMi the whole time. locationContext.stations was populated and
  // this screen never read it.
  //
  // Falls back to the distance-to-centre line when a property has no station,
  // rather than dropping the row.
  Widget _buildPropertyCard(StayListing l) {
    final String cover = l.photos.isNotEmpty ? l.photos.first.url : '';
    final String? headline = l.locationContext?.partnerCounts.headline;
    final StayLocationContext? ctx = l.locationContext;
    final StayStation? station =
        (ctx != null && ctx.stations.isNotEmpty) ? ctx.stations.first : null;

    return InkWell(
      onTap: () => Navigator.of(context).pushNamed(
        StayRoutes.listing,
        arguments: {'listingId': l.id},
      ),
      borderRadius: BorderRadius.circular(14),
      child: Container(
        decoration: BoxDecoration(
          color: GoOutsColors.cardSurface,
          borderRadius: BorderRadius.circular(14),
          boxShadow: const <BoxShadow>[
            BoxShadow(
              color: GoOutsColors.cardShadow,
              blurRadius: 10,
              offset: Offset(0, 3),
            ),
          ],
        ),
        clipBehavior: Clip.antiAlias,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Stack(
              children: <Widget>[
                cover.isEmpty
                    ? Container(
                        height: 200,
                        width: double.infinity,
                        color: GoOutsColors.dividerGray,
                        child: const Icon(Icons.home_outlined,
                            size: 40, color: GoOutsColors.outlineVariant),
                      )
                    : Image.network(
                        cover,
                        height: 200,
                        width: double.infinity,
                        fit: BoxFit.cover,
                        // Decoded at roughly display width. A full resolution
                        // decode per card is how a list eats memory, and this
                        // app has been killed by iOS for that before.
                        cacheWidth: 800,
                        errorBuilder: (_, __, ___) => Container(
                          height: 200,
                          color: GoOutsColors.dividerGray,
                          child: const Icon(Icons.broken_image_outlined,
                              color: GoOutsColors.outlineVariant),
                        ),
                      ),
                // Cashback stays on the photograph. It is a real figure and it
                // is not the same claim as the partner count below.
                if (_rate.isKnown)
                  Positioned(
                    right: 10,
                    top: 10,
                    child: _photoChip(
                      '${_rate.label} back',
                      colour: GoOutsColors.tealSecondary,
                    ),
                  ),
                Positioned(left: 10, top: 10, child: _saveButton(l)),
              ],
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: <Widget>[
                      Expanded(
                        child: Text(
                          l.title,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: GoogleFonts.inter(
                            fontSize: 14,
                            height: 20 / 14,
                            fontWeight: FontWeight.w600,
                            color: GoOutsColors.deepNavy,
                          ),
                        ),
                      ),
                      // A rating of zero is "no reviews yet", not "nought out
                      // of five". Showing 0.0 would libel a new listing.
                      if (l.ratingCount > 0) ...<Widget>[
                        const SizedBox(width: 8),
                        Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 8, vertical: 3),
                          decoration: BoxDecoration(
                            color: GoOutsColors.paleBlueTint,
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: <Widget>[
                              const Icon(Icons.star_border_rounded,
                                  size: 14, color: GoOutsColors.primaryBlue),
                              const SizedBox(width: 3),
                              Text(
                                l.ratingAvg.toStringAsFixed(1),
                                style: GoogleFonts.inter(
                                    fontSize: 12,
                                    height: 16 / 12,
                                    fontWeight: FontWeight.w600,
                                    color: GoOutsColors.primaryBlue),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ],
                  ),
                  const SizedBox(height: 6),
                  if (station != null)
                    Text(
                      // Exactly the shape Stitch draws, from data we already
                      // hold. "miles", never "minutes": walkMi is a distance.
                      '${station.walkMi.toStringAsFixed(1)} miles from '
                      '${station.name}, ${station.linesLabel}',
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: GoogleFonts.inter(
                          fontSize: 13.5,
                          height: 20 / 13.5,
                          color: GoOutsColors.bodyText),
                    )
                  else if (ctx != null && ctx.centreName.isNotEmpty)
                    Text(
                      '${ctx.distanceToCentreMi.toStringAsFixed(1)} miles '
                      'from ${ctx.centreName}',
                      style: GoogleFonts.inter(
                          fontSize: 13.5,
                          height: 20 / 13.5,
                          color: GoOutsColors.bodyText),
                    ),
                ],
              ),
            ),

            // ⚠ THE BANNER. Full width, solid, and the loudest thing on the
            // card. Hidden entirely when headline is null, which is what it
            // returns when there is genuinely nothing nearby to claim.
            if (headline != null) ...<Widget>[
              const SizedBox(height: 12),
              Container(
                width: double.infinity,
                color: GoOutsColors.primaryBlue,
                padding:
                    const EdgeInsets.symmetric(horizontal: 16, vertical: 11),
                child: Row(
                  children: <Widget>[
                    const Icon(Icons.verified_rounded,
                        size: 17, color: Colors.white),
                    const SizedBox(width: 9),
                    Expanded(
                      child: Text(
                        headline,
                        style: GoogleFonts.inter(
                          fontSize: 13.5,
                          height: 20 / 13.5,
                          fontWeight: FontWeight.w700,
                          color: Colors.white,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ] else
              const SizedBox(height: 12),

            // Price and the call to action, as Stitch lays them out.
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 14),
              child: Row(
                children: <Widget>[
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Text('Total per night',
                            style: GoogleFonts.inter(
                                fontSize: 12,
                                height: 16 / 12,
                                color: GoOutsColors.bodyText)),
                        Text(l.nightlyRate.compact,
                            style: GoogleFonts.inter(
                                fontSize: 20,
                                height: 28 / 20,
                                fontWeight: FontWeight.w700,
                                color: GoOutsColors.deepNavy)),
                      ],
                    ),
                  ),
                  FilledButton(
                    onPressed: () => Navigator.of(context).pushNamed(
                      StayRoutes.listing,
                      arguments: {'listingId': l.id},
                    ),
                    style: FilledButton.styleFrom(
                      backgroundColor: GoOutsColors.primaryBlue,
                      padding: const EdgeInsets.symmetric(
                          horizontal: 20, vertical: 14),
                      shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(10)),
                    ),
                    child: Text('View property',
                        style: GoogleFonts.inter(
                            fontSize: 14,
                            fontWeight: FontWeight.w600,
                            color: Colors.white)),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// ── ⚠ THE HEART. setSaved AND watchSaved EXISTED AND NOTHING CALLED THEM. ──
  ///
  /// StayListingService has carried both since the service was written, with a
  /// comment describing saving as "the only listing related write a guest may
  /// make". No screen ever used either, so the feature was complete and
  /// unreachable. Stitch draws the heart on this card, so here it is.
  ///
  /// Streamed per card rather than loaded once, because a guest who saves a
  /// property on the detail screen and comes back should see it filled in
  /// without a refresh.
  Widget _saveButton(StayListing l) => StreamBuilder<bool>(
        stream: StayListingService.instance.watchSaved(l.id),
        builder: (BuildContext c, AsyncSnapshot<bool> snap) {
          final bool saved = snap.data ?? false;
          return Material(
            color: Colors.white,
            shape: const CircleBorder(),
            child: InkWell(
              customBorder: const CircleBorder(),
              onTap: () => StayListingService.instance.setSaved(l.id, !saved),
              child: Padding(
                padding: const EdgeInsets.all(7),
                child: Icon(
                  saved ? Icons.favorite : Icons.favorite_border,
                  size: 19,
                  color:
                      saved ? GoOutsColors.error : GoOutsColors.deepNavy,
                ),
              ),
            ),
          );
        },
      );
}
